  const [deck,setDeck]=useState<string[]>(rosters.Autobot.slice(0,9).map(x=>x.id)),[filter,setFilter]=useState("All"),[factionFilter,setFactionFilter]=useState<"All"|Faction>("All");
  const [board,setBoard]=useState<Slot[]>(Array(9).fill(null)),[enemyBoard,setEnemyBoard]=useState<Slot[]>(Array(9).fill(null)),[hand,setHand]=useState<Unit[]>([]),[backups,setBackups]=useState<Unit[]>([]),[enemyBackups,setEnemyBackups]=useState<Unit[]>([]);
  const [scrap,setScrap]=useState<Unit[]>([]),[enemyScrap,setEnemyScrap]=useState<Unit[]>([]),[enemyRoster,setEnemyRoster]=useState<Unit[]>([]),[battleHand,setBattleHand]=useState<string[]>([]),[drawPile,setDrawPile]=useState<string[]>([]);
  const [round,setRound]=useState(1),[actions,setActions]=useState(3),[repositions,setRepositions]=useState(2),[battlePlayed,setBattlePlayed]=useState(false),[usedAttacks,setUsedAttacks]=useState<string[]>([]),[usedAbilities,setUsedAbilities]=useState<string[]>([]);
  const [interaction,setInteraction]=useState<Interaction>(null),[dragSource,setDragSource]=useState<DragSource|null>(null),[revealed,setRevealed]=useState<number[]>([]),[traps,setTraps]=useState<number[]>([]),[armored,setArmored]=useState<string|null>(null),[faceOff,setFaceOff]=useState(false),[darkDamage,setDarkDamage]=useState<number|null>(null),[grimlockFrenzyRound,setGrimlockFrenzyRound]=useState<number|null>(null),[scoutBuff,setScoutBuff]=useState<string[]>([]),[enemyDefeatPending,setEnemyDefeatPending]=useState(false),[quietRounds,setQuietRounds]=useState(0),[roundDamage,setRoundDamage]=useState(false);
  const [feedback,setFeedback]=useState<Feedback>({text:"Build your team and take command.",tone:"info",key:0}),[log,setLog]=useState<string[]>([]),[winner,setWinner]=useState(""),[multiplayerSocket,setMultiplayerSocket]=useState<Socket|null>(null),[hitSpaces,setHitSpaces]=useState<number[]>([]);
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem("hidden-front-theme",theme)},[theme]);
  useEffect(()=>{const saved=localStorage.getItem("hidden-front-theme");if(saved&&themes.some(([id])=>id===saved))setTheme(saved)},[]);
  useEffect(()=>{if(!multiplayerSocket)return;const ready=(data:{opponent:string[]})=>{const roster=data.opponent.map(id=>allUnits.find(unit=>unit.id===id)).filter((unit):unit is Unit=>!!unit).map(unit=>({...unit,hp:unit.max,canAttack:true,shield:unit.id==="terror"?1:0}));setEnemyRoster(roster);setPhase("opponent");flash("Both decks are locked. Enemy team intelligence is now available.","good")};const deployed=(data:{opponent:{board:(string|null)[];backups:string[]}})=>{const board=data.opponent.board.map(id=>id?allUnits.find(unit=>unit.id===id)??null:null).map(unit=>unit?{...unit,hp:unit.max,canAttack:true,shield:unit.id==="terror"?1:0}:null);const backups=data.opponent.backups.map(id=>allUnits.find(unit=>unit.id===id)).filter((unit):unit is Unit=>!!unit).map(unit=>({...unit,hp:unit.max,canAttack:true,shield:unit.id==="terror"?1:0}));setEnemyBoard(board);setEnemyBackups(backups);setPhase("combat");flash("Both teams are deployed. Round 1 begins.","good")};multiplayerSocket.on("decks-ready",ready);multiplayerSocket.on("deployments-ready",deployed);multiplayerSocket.on("match-status",(text:string)=>flash(text,"info"));return()=>{multiplayerSocket.off("decks-ready",ready);multiplayerSocket.off("deployments-ready",deployed);multiplayerSocket.off("match-status")}},[multiplayerSocket]);
  const built=useMemo(()=>deck.map(id=>allUnits.find(x=>x.id===id)!).filter(Boolean),[deck]);
  const count=(role:string)=>built.filter(x=>x.role===role).length,legal=validateDeck(built),playerLeft=board.filter(Boolean).length+backups.length+hand.length,enemyLeft=enemyBoard.filter(Boolean).length+enemyBackups.length,reinforcementsNeeded=Math.min(Math.max(0,6-board.filter(Boolean).length),backups.length);
  const flash=(text:string,tone:Feedback["tone"]="info")=>{setFeedback({text,tone,key:Date.now()});setLog(v=>[text,...v].slice(0,100))};
  const mutateUnit=(list:Slot[],index:number,unit:Unit|null)=>list.map((x,i)=>i===index?unit:x);
