  function healWeakest(factionName:Faction,amount:number){setBoard(v=>{const candidates=v.map((u,i)=>({u,i})).filter((x):x is {u:Unit;i:number}=>!!x.u&&x.u.faction===factionName&&x.u.hp<x.u.max).sort((a,b)=>a.u.hp-a.u.max-(b.u.hp-b.u.max));if(!candidates.length)return v;const chosen=candidates[0];flash(`${chosen.u.name} healed ${amount} Health from a triggered ability.`,"good");return v.map((u,i)=>i===chosen.i&&u?{...u,hp:Math.min(u.max,u.hp+amount)}:u)})}

  function prepareOpponent(){if(multiplayerSocket){multiplayerSocket.emit("submit-deck",deck);flash("Deck locked. Waiting for your opponent to finish building.","info");return}const roster=(enemyFaction==="Random"?randomEnemyDeck():enemyDeck(enemyFaction)).map(unit=>({...unit,hp:unit.max,canAttack:true,shield:unit.id==="terror"?1:0}));setEnemyRoster(roster);setEnemyScrap([]);setPhase("opponent")}
  function beginDeployment(){const chosenDeck=built.map(x=>({...x,hp:x.max,canAttack:true,shield:x.id==="terror"?1:0})),enemy=shuffled(enemyRoster.map(unit=>({...unit})));const enemySlots=shuffled([0,1,2,3,4,5,6,7,8]).slice(0,6),eBoard:Slot[]=Array(9).fill(null);if(!multiplayerSocket)enemySlots.forEach((slot,i)=>eBoard[slot]=enemy[i]);setBoard(Array(9).fill(null));setHand(chosenDeck);setBackups([]);setEnemyBoard(eBoard);setEnemyBackups(multiplayerSocket?[]:enemy.slice(6));setScrap([]);setLog([]);setRound(1);setRevealed([]);setHitSpaces([]);setTraps([]);setDragSource(null);setInteraction(null);flash("Choose any six of your nine characters and place them on your grid.");setPhase("deploy")}
