  function startCombat(){if(hand.length!==3||board.filter(Boolean).length!==6)return;const pile=makeBattleDeck(),deployed=applyDivebombAura(board);setBackups(hand);setHand([]);setBoard(deployed);setEnemyBoard(v=>applyDivebombAura(v));setBattleHand(pile.slice(0,1));setDrawPile(pile.slice(1));setActions(3);setBattlePlayed(false);setUsedAttacks([]);setUsedAbilities([]);if(multiplayerSocket){multiplayerSocket.emit("submit-deployment",{board:deployed.map(unit=>unit?.id??null),backups:hand.map(unit=>unit.id)});setPhase("waiting");flash("Your starting six are locked. Waiting for the other player to deploy.","info");return}setPhase("combat");flash("Round 1. Your three unplaced characters became Backups; the Battle Card window is open.","good")}
  function effectiveDamage(unit:Unit){let dmg=unit.dmg;const bee=board.some(x=>x?.id==="bee"),autobotCommander=board.some(x=>x?.faction==="Autobot"&&x.role==="Commander");if(bee&&autobotCommander&&(unit.id==="bee"||(unit.faction==="Autobot"&&unit.role==="Commander")))dmg+=5;if(scoutBuff.includes(unit.id))dmg+=5;return dmg}
  function selectAttacker(index:number){const u=board[index];if(phase!=="combat"||!u||!u.canAttack||actions===0)return;if(usedAbilities.includes(u.id)){flash(`${u.name} already used an ability instead of attacking this round.`,"bad");return}const times=usedAttacks.filter(id=>id===u.id).length,limit=u.id==="grimlock"&&grimlockFrenzyRound===round?3:u.id==="sun"&&board.some(x=>x?.id==="side")&&u.abilityUses>0?2:1;if(times>=limit){flash(`${u.name} has already used every permitted attack this round.`,"bad");return}setInteraction({kind:"attack",actor:index});setBattlePlayed(true);flash(`${u.name} selected. Choose an enemy position.`)}
